from __future__ import annotations

import hashlib
import json
import unicodedata
from typing import Any, Mapping

GENESIS = "GENESIS"


def normalize_key(key: str) -> str:
    return unicodedata.normalize("NFC", key)


def canonical_bytes(line: Mapping[str, Any]) -> bytes:
    return json.dumps(
        line,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")


def _without_hash_fields(line: Mapping[str, Any]) -> dict[str, Any]:
    return {k: v for k, v in line.items() if k != "hash" and k != "prev_hash"}


def line_hash(prev_hash: str, line: Mapping[str, Any]) -> str:
    emptied = _without_hash_fields(line)
    canonical = canonical_bytes(emptied)
    payload = (prev_hash + "|" + canonical.decode("utf-8")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

