from __future__ import annotations

import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from ledgerlock.format import GENESIS, canonical_bytes, line_hash, normalize_key


class ConflictError(Exception):
    def __init__(
        self,
        key: str,
        incoming_rid: str,
        committed_rid: str,
        batch_index: int | None = None,
    ) -> None:
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        super().__init__(
            f"conflict on key {key!r}: committed rid {committed_rid!r} "
            f"!= incoming rid {incoming_rid!r}"
        )


@dataclass
class AppendResult:
    line: dict[str, Any]
    committed: bool
    replayed: bool


class Ledger:
    def __init__(self, path: str | os.PathLike[str]) -> None:
        self._path = Path(path)

    @property
    def path(self) -> Path:
        return self._path

    def _read_tail(self) -> dict[str, Any] | None:
        from ledgerlock.store import read_lines

        try:
            lines = read_lines(self._path)
        except FileNotFoundError:
            return None
        if not lines:
            return None
        return json.loads(lines[-1].decode("utf-8"))

    def append(self, op: tuple) -> AppendResult:
        if len(op) == 5 and op[0] == "put":
            kind, key, value, rid, ts = op
        elif len(op) == 4 and op[0] == "delete":
            kind, key, rid, ts = op
            value = None
        else:
            raise ValueError(f"unsupported op tuple: {op!r}")

        normalized_key = normalize_key(key)
        if normalized_key == "":
            raise ValueError("key must be non-empty after NFC normalization")

        tail = self._read_tail()
        if tail is None:
            prev_hash = GENESIS
        else:
            prev_hash = tail["hash"]

        if kind == "put":
            line: dict[str, Any] = {
                "op": "put",
                "key": normalized_key,
                "value": value,
                "ts": ts,
                "id": rid,
            }
        else:
            line = {
                "op": "delete",
                "key": normalized_key,
                "ts": ts,
                "id": rid,
            }

        line["prev_hash"] = prev_hash
        line["hash"] = line_hash(prev_hash, line)
        line_bytes = canonical_bytes(line) + b"\n"

        self._append_bytes(line_bytes)

        return AppendResult(line=line, committed=True, replayed=False)

    def _append_bytes(self, data: bytes) -> None:
        from ledgerlock.store import read_lines

        try:
            existing = read_lines(self._path)
        except FileNotFoundError:
            existing = []
        new_lines = list(existing) + [data.rstrip(b"\n")]
        from ledgerlock.store import write_atomic

        if not self._path.parent.exists():
            self._path.parent.mkdir(parents=True, exist_ok=True)
        write_atomic(self._path, (line + b"\n" for line in new_lines))

