import argparse
import sys
from typing import NoReturn

from ledgerlock.ledger import Ledger


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="ledgerlock",
        description="Append-only tamper-evident key/value ledger.",
    )
    sub = parser.add_subparsers(dest="command")

    verify = sub.add_parser("verify", help="verify a ledger")
    verify.add_argument("ledger")

    snapshot = sub.add_parser("snapshot", help="snapshot a ledger")
    snapshot.add_argument("ledger")
    snapshot.add_argument("--out")

    apply = sub.add_parser("apply", help="apply a batch")
    apply.add_argument("ledger")
    apply.add_argument("--batch")

    repair = sub.add_parser("repair-tail", help="repair truncated tail")
    repair.add_argument("ledger")

    sub.add_parser("version", help="print version")

    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return int(exc.code) if exc.code is not None else 2

    if args.command is None:
        parser.print_help(sys.stderr)
        return 2
    if args.command == "version":
        print("ledgerlock 0.1.0")
        return 0
    if args.command == "verify":
        return _cmd_verify(args)
    if args.command == "snapshot":
        return _cmd_snapshot(args)
    if args.command == "apply":
        return _cmd_apply(args)
    if args.command == "repair-tail":
        return _cmd_repair_tail(args)

    parser.print_help(sys.stderr)
    return 2


def _cmd_verify(args: argparse.Namespace) -> int:
    try:
        ledger = Ledger(args.ledger)
    except FileNotFoundError:
        print(f"ledger not found: {args.ledger}", file=sys.stderr)
        return 3
    return 0


