def _cmd_apply(args: argparse.Namespace) -> int:
    return 0


def _cmd_repair_tail(args: argparse.Namespace) -> int:
    return 0


def _usage_error(message: str) -> NoReturn:
    print(message, file=sys.stderr)
    raise SystemExit(2)

