"""Tests for STORY-01-01: package skeleton, NFC normalization, CLI surface."""

from __future__ import annotations

import re
import subprocess
import sys
import unittest
from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parent.parent


class NfcNormalizationTest(unittest.TestCase):
    def test_normalize_nfc_byte_for_byte(self) -> None:
        from ledgerlock.format import normalize_key
        s = "Café"
        self.assertEqual(normalize_key(s), s)
        import unicodedata
        self.assertEqual(normalize_key(s), unicodedata.normalize("NFC", s))

    def test_nfc_and_nfd_become_byte_identical(self) -> None:
        from ledgerlock.format import normalize_key
        nfc = "\u00e9"
        nfd = "e\u0301"
        self.assertEqual(normalize_key(nfc), normalize_key(nfd))
        self.assertEqual(normalize_key(nfd), "\u00e9")


class PackageImportTest(unittest.TestCase):
    def test_import_ledgerlock(self) -> None:
        import ledgerlock
        self.assertTrue(ledgerlock.__file__.endswith("ledgerlock/__init__.py"))

    def test_no_disallowed_imports(self) -> None:
        forbidden = (
            r"^(import|from) (socket|subprocess|requests|http|urllib|asyncio|"
            r"ssl|multiprocessing|ctypes|http\.server|http\.client|socketserver)"
        )
        for path in (REPO_ROOT / "ledgerlock").rglob("*.py"):
            content = path.read_text(encoding="utf-8")
            for line in content.splitlines():
                if re.match(forbidden, line):
                    self.fail(f"disallowed import in {path}: {line}")

    def test_no_os_system_subprocess_socket_calls(self) -> None:
        forbidden = re.compile(r"os\.system|subprocess\.|socket\.")
        for path in (REPO_ROOT / "ledgerlock").rglob("*.py"):
            content = path.read_text(encoding="utf-8")
            for n, line in enumerate(content.splitlines(), 1):
                if forbidden.search(line):
                    self.fail(
                        f"disallowed call in {path}:{n}: {line}"
                    )

    def test_ledger_and_conflict_error_importable(self) -> None:
        from ledgerlock import ConflictError, Ledger
        self.assertTrue(callable(Ledger))


class CliSurfaceTest(unittest.TestCase):
    def test_extra_positional_argparse_exits_two(self) -> None:
        result = subprocess.run(
            [
                sys.executable,
                "-m",
                "ledgerlock",
                "verify",
                "some.jsonl",
                "extra-positional",
            ],
            cwd=str(REPO_ROOT),
            capture_output=True,
            text=True,
        )
        self.assertEqual(result.returncode, 2)

"""Tests for STORY-01-02: format.canonical_bytes and GENESIS."""

from __future__ import annotations

import json
import unittest


class CanonicalBytesTest(unittest.TestCase):
    def test_matches_spec_signature(self) -> None:
        from ledgerlock.format import canonical_bytes

        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        expected = json.dumps(
            line,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
        self.assertEqual(canonical_bytes(line), expected)

    def test_same_dict_same_bytes(self) -> None:
        from ledgerlock.format import canonical_bytes

        a = {"op": "put", "key": "k", "value": {"x": 1, "y": 2}, "ts": 1, "id": "r"}
        b = {"op": "put", "key": "k", "value": {"x": 1, "y": 2}, "ts": 1, "id": "r"}
        self.assertEqual(canonical_bytes(a), canonical_bytes(b))

    def test_non_ascii_utf8_literal(self) -> None:
        from ledgerlock.format import canonical_bytes

        line = {"key": "é"}
        result = canonical_bytes(line)
        self.assertIn(b"\xc3\xa9", result)
        self.assertNotIn(b"\\u00e9", result)
        self.assertEqual(result, canonical_bytes(line))

    def test_key_order_does_not_matter(self) -> None:
        from ledgerlock.format import canonical_bytes

        a = {"a": 1, "b": 2, "c": 3}
        b = {"c": 3, "b": 2, "a": 1}
        self.assertEqual(canonical_bytes(a), canonical_bytes(b))

    def test_round_trip_through_json_loads(self) -> None:
        from ledgerlock.format import canonical_bytes

        original = {"x": 1, "y": [1, 2, 3], "z": {"k": "v"}}
        first = canonical_bytes(original)
        roundtripped = json.loads(first.decode("utf-8"))
        second = canonical_bytes(roundtripped)
        self.assertEqual(first, second)


class GenesisConstantTest(unittest.TestCase):
    def test_genesis_literal(self) -> None:
        from ledgerlock.format import GENESIS
        self.assertEqual(GENESIS, "GENESIS")
        self.assertEqual(len(GENESIS), 7)

"""Tests for STORY-01-03: format.line_hash SHA-256 hex digest."""

from __future__ import annotations

import hashlib
import unittest


class LineHashTest(unittest.TestCase):
    def test_returns_64_lowercase_hex(self) -> None:
        from ledgerlock.format import line_hash
        h = line_hash("abc", {"op": "put", "key": "k"})
        self.assertEqual(len(h), 64)
        self.assertTrue(all(c in "0123456789abcdef" for c in h))
        self.assertEqual(h, h.lower())

    def test_distinct_prev_hash_distinct_digest(self) -> None:
        from ledgerlock.format import line_hash
        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        h1 = line_hash("a" * 64, line)
        h2 = line_hash("b" * 64, line)
        self.assertNotEqual(h1, h2)

    def test_ignores_existing_hash_fields(self) -> None:
        from ledgerlock.format import canonical_bytes, line_hash

        line_no_fields = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        line_with_fields = {
            **line_no_fields,
            "prev_hash": "X" * 64,
            "hash": "Y" * 64,
        }
        prev = "Z" * 64
        self.assertEqual(line_hash(prev, line_no_fields), line_hash(prev, line_with_fields))

    def test_deterministic(self) -> None:
        from ledgerlock.format import line_hash
        prev = "p" * 64
        line = {"a": 1, "b": 2}
        self.assertEqual(line_hash(prev, line), line_hash(prev, line))

    def test_genesis_prev_hash_accepted(self) -> None:
        from ledgerlock.format import GENESIS, line_hash
        h = line_hash(GENESIS, {"a": 1})
        self.assertEqual(len(h), 64)

    def test_known_vector_matches_sha256(self) -> None:
        from ledgerlock.format import canonical_bytes, line_hash
        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        emptied = {k: v for k, v in line.items() if k not in ("hash", "prev_hash")}
        expected = hashlib.sha256(
            b"GENESIS|" + canonical_bytes(emptied)
        ).hexdigest()
        self.assertEqual(line_hash("GENESIS", line), expected)

